"""Article-specific editorial source for CC-06 (Civil Code arts. 115-250)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "115": row("A representação pode nascer diretamente da lei ou da vontade da pessoa representada.", "Na representação legal, a norma atribui poderes a alguém para agir por outra pessoa. Na voluntária, o próprio interessado concede esses poderes, normalmente por mandato. Em ambos os casos, é indispensável identificar a origem e os limites da autorização.", "Os pais representam o filho nas hipóteses legais; um proprietário também pode nomear procurador para vender determinado bem.", "Representação não transfere a titularidade do direito. O representante atua em nome alheio e deve permanecer dentro dos poderes recebidos.", "Representação", "atuação juridicamente reconhecida de uma pessoa em nome de outra"),
    "116": row("A declaração feita pelo representante dentro dos poderes recebidos produz efeitos diretamente para o representado.", "Quando age validamente em nome de outra pessoa, o representante não se torna parte econômica do negócio: direitos e obrigações recaem sobre o representado. Esse efeito direto depende de atuação dentro do poder legal ou voluntariamente conferido.", "Procurador autorizado assina contrato de locação em nome do proprietário; o proprietário passa a ser locador.", "Se o representante ultrapassar seus poderes, não se aplica automaticamente o efeito previsto neste artigo; devem ser examinadas responsabilidade, ratificação e regras próprias.", "Representado", "pessoa em cujo nome o representante pratica o ato"),
    "117": row("Em regra, é anulável o negócio em que o representante contrata consigo mesmo, direta ou indiretamente, salvo autorização da lei ou do representado.", "O autocontrato cria risco de favorecimento porque a mesma pessoa ocupa posições contrapostas. A proibição alcança também o negócio feito por quem recebeu poderes em subestabelecimento. A autorização válida afasta a regra geral de anulabilidade.", "Procurador encarregado de vender um imóvel compra o bem para si sem permissão específica do proprietário.", "O negócio não é automaticamente inexistente ou nulo: a consequência indicada é anulabilidade, sujeita às regras e aos prazos correspondentes.", "Autocontrato", "negócio em que a mesma pessoa atua nos dois lados da relação representativa"),
    "118": row("O representante deve demonstrar a terceiros sua condição e a extensão dos poderes que recebeu.", "Quem negocia em nome alheio precisa tornar verificável o título de representação. Se não comprovar os poderes e os exceder, poderá responder pessoalmente pelos atos praticados além da autorização.", "Antes de assinar a venda, o procurador apresenta a procuração que limita preço e forma de pagamento.", "A simples afirmação de que se representa alguém não basta quando o terceiro exige prova. Também é necessário conferir prazo, objeto e eventuais restrições do instrumento.", "Extensão dos poderes", "conjunto de atos e limites abrangidos pela autorização representativa"),
    "119": row("O negócio feito em conflito de interesses pode ser anulado quando o terceiro sabia ou deveria saber do conflito.", "A proteção depende de incompatibilidade entre o interesse do representante e o do representado, somada à ciência real ou exigível da outra parte. O pedido de anulação está sujeito a decadência de cento e oitenta dias, contados da conclusão do negócio ou do fim da incapacidade.", "Representante vende bem do representado a empresa que controla, e a compradora conhece a situação.", "Conflito de interesses não se presume apenas porque o resultado foi desfavorável. Devem ser demonstrados o conflito e o conhecimento exigido pelo artigo.", "Decadência", "perda do direito de pedir determinada medida após o prazo legal"),
    "120": row("A representação legal segue as normas específicas aplicáveis; a voluntária observa as regras da Parte Especial do Código.", "O artigo encaminha cada modalidade ao seu regime próprio. Poder familiar, tutela ou curatela não se confundem com mandato concedido por vontade do interessado. Fonte, alcance, prestação de contas e extinção dos poderes podem variar.", "Para saber os poderes de um tutor consulta-se a disciplina da tutela; para um procurador, as regras do mandato.", "Não se devem transportar automaticamente regras do mandato para toda representação legal. A norma específica da relação tem prioridade.", "Representação voluntária", "representação criada por manifestação de vontade do interessado"),
    "121": row("Condição é cláusula voluntária que faz os efeitos do negócio dependerem de acontecimento futuro e incerto.", "O evento ainda não ocorreu e pode ou não acontecer. Isso distingue condição de termo, que se refere a acontecimento futuro certo. A cláusula deve resultar da vontade das partes, e não de requisito imposto diretamente pela lei.", "Doação prevê que o bem será transferido se o beneficiário concluir determinado curso.", "Nem toda referência ao futuro é condição. É preciso verificar se há incerteza do evento e se os efeitos do negócio foram realmente subordinados a ele.", "Condição", "cláusula que vincula efeitos do negócio a evento futuro e incerto"),
    "122": row("Condições são admitidas quando respeitam lei, ordem pública e bons costumes, mas não podem eliminar todo efeito do negócio nem deixá-lo ao puro arbítrio de uma parte.", "A autonomia privada permite modelar efeitos futuros, porém não legitima cláusula ilícita, contraditória com valores obrigatórios ou meramente potestativa. A condição deve conservar conteúdo juridicamente controlável.", "Contrato não pode depender apenas de o devedor decidir, sem qualquer parâmetro, se deseja cumprir.", "Condição ligada à conduta de uma parte não é sempre proibida. O defeito está no puro arbítrio, sem fator objetivo ou compromisso juridicamente apreciável.", "Condição potestativa", "condição relacionada à vontade de uma parte; será vedada quando submetida ao seu puro arbítrio"),
    "123": row("Invalidam o negócio as condições suspensivas impossíveis, as condições ilícitas ou voltadas a ato ilícito e as incompreensíveis ou contraditórias.", "Esses defeitos atingem o negócio subordinado à condição. A impossibilidade física ou jurídica recebe aqui tratamento específico quando a condição é suspensiva, pois impede a aquisição do direito pretendido.", "Promessa condicionada a fato fisicamente impossível não produz validamente o efeito suspenso.", "O artigo trata de invalidação do negócio, não apenas de desconsideração da cláusula. Condições resolutivas impossíveis seguem regra diferente no artigo seguinte.", "Condição suspensiva", "cláusula que impede a aquisição do direito enquanto o evento não ocorre"),
    "124": row("A condição resolutiva impossível e a condição de não fazer algo impossível são tratadas como inexistentes.", "Nessas hipóteses, elimina-se a condição sem invalidar, por esse motivo, o negócio. O resultado difere da condição suspensiva impossível prevista no artigo anterior.", "Contrato prevê sua extinção se ocorrer evento fisicamente impossível; essa cláusula resolutiva é desconsiderada.", "A solução depende da espécie de condição. Não se deve aplicar esta regra a condição ilícita nem confundir inexistência da cláusula com inexistência do negócio inteiro.", "Condição resolutiva", "cláusula que extingue o direito quando o evento futuro e incerto acontece"),
    "125": row("Enquanto a condição suspensiva não ocorrer, o direito pretendido pelo negócio ainda não é adquirido.", "O negócio existe, mas a aquisição do direito permanece pendente do evento futuro e incerto. Antes do implemento, há expectativa juridicamente protegida, não o direito definitivo que a cláusula condicionou.", "Comprador só adquirirá determinado direito se obtiver licença prevista como condição suspensiva.", "A pendência não autoriza destruir a expectativa da outra parte. O titular eventual pode praticar atos conservatórios conforme o art. 130.", "Implemento da condição", "ocorrência do evento previsto na cláusula condicional"),
    "126": row("Disposições posteriores sobre a coisa, feitas enquanto pende condição suspensiva, perdem eficácia quando incompatíveis com o direito que surge após a condição.", "A regra protege quem adquire o direito condicionado. O titular provisório não pode frustrar o efeito futuro mediante ato incompatível praticado durante a pendência.", "Bem prometido sob condição é depois transferido de forma incompatível; cumprida a condição, examina-se a ineficácia do ato posterior.", "A incompatibilidade precisa ser demonstrada. O artigo não declara sem efeito toda disposição posterior nem dispensa a análise de terceiros e de regras registrais.", "Direito eventual", "posição jurídica dependente da realização de condição ainda pendente"),
    "127": row("Na condição resolutiva, o negócio e o direito produzem efeitos desde o início, até que o evento previsto aconteça.", "Diferentemente da condição suspensiva, o titular pode exercer imediatamente o direito. A ocorrência futura e incerta atua para extinguir a situação jurídica.", "Contrato vigora desde a assinatura, mas será resolvido se a licença essencial for definitivamente cancelada.", "O direito atual não é definitivo enquanto a condição estiver pendente. Seu exercício deve respeitar boa-fé e os efeitos próprios da eventual resolução.", "Resolução", "extinção dos efeitos do negócio em razão de causa prevista na lei ou no próprio negócio"),
    "128": row("Realizada a condição resolutiva, extingue-se o direito; em relações continuadas, atos anteriores compatíveis e praticados de boa-fé podem ser preservados.", "A resolução normalmente opera sobre o direito condicionado, mas a lei protege a estabilidade de prestações periódicas já executadas quando a natureza da condição e a boa-fé justificam.", "Encerrada locação por evento resolutivo, pagamentos e usos regulares anteriores não são automaticamente desfeitos.", "As partes podem estabelecer solução diferente dentro dos limites legais. A preservação dos atos anteriores exige compatibilidade com a natureza da condição e boa-fé.", "Execução continuada", "relação cujos efeitos se prolongam ou se repetem ao longo do tempo"),
    "129": row("A lei neutraliza a interferência maliciosa de quem impede ou provoca a condição em benefício próprio.", "Se a parte desfavorecida pela ocorrência impede deslealmente o evento, a condição é considerada realizada. Se quem seria beneficiado a provoca maliciosamente, ela é tratada como não ocorrida. A regra protege boa-fé e impede vantagem obtida por manipulação.", "Devedor sabota vistoria necessária para impedir a condição que liberaria pagamento ao credor.", "É indispensável demonstrar atuação maliciosa e nexo com o evento. A mera dificuldade ou cooperação legítima não produz automaticamente a ficção legal.", "Ficção jurídica", "tratamento legal de um fato como ocorrido ou não ocorrido para produzir determinado efeito"),
    "130": row("O titular de direito sujeito a condição pode praticar medidas destinadas a conservá-lo.", "Embora o direito definitivo ainda dependa da condição ou possa ser resolvido, a lei permite providências preventivas contra perda, deterioração ou frustração. A medida deve conservar, não antecipar indevidamente, o exercício pleno.", "Beneficiário pede providência para impedir a destruição do bem enquanto aguarda a condição.", "Atos conservatórios não equivalem a exigir desde logo a prestação condicionada. A adequação depende do risco e da natureza do direito eventual.", "Ato conservatório", "medida voltada a preservar um direito ameaçado sem antecipar seu exercício integral"),
    "131": row("O termo inicial impede o exercício imediato, mas o direito já é adquirido.", "Como o termo corresponde a evento futuro certo, a existência do direito não fica em dúvida; apenas sua exigibilidade ou exercício aguarda a data ou acontecimento fixado.", "Crédito constituído hoje será cobrável somente na data de vencimento prevista.", "Termo inicial não se confunde com condição suspensiva: na condição, o evento é incerto e o direito ainda não foi adquirido.", "Termo inicial", "marco futuro e certo a partir do qual o direito poderá ser exercido"),
    "132": row("A contagem civil exclui o dia inicial e inclui o vencimento, com regras para feriado, metade do mês, meses, anos e horas.", "Salvo norma ou convenção diversa, o prazo termina no dia correspondente ao início; se não houver dia igual, vence no imediatamente seguinte. Vencimento em feriado prorroga-se ao próximo dia útil, e prazos por hora correm minuto a minuto.", "Prazo iniciado no dia 10 começa a ser contado no dia 11 e inclui o último dia.", "Regras processuais, administrativas ou especiais podem adotar contagem diferente. Antes de calcular, identifique a natureza do prazo e a norma aplicável.", "Cômputo do prazo", "método usado para determinar o começo, a duração e o vencimento de um prazo"),
    "133": row("Presume-se que o prazo beneficia o herdeiro no testamento e o devedor no contrato, salvo indicação de benefício do credor ou de ambos.", "A presunção ajuda a decidir quem pode renunciar ao prazo ou antecipar a prestação. O instrumento e as circunstâncias podem mostrar que a proteção foi estabelecida para outra parte ou de forma comum.", "Devedor pode pagar antes do vencimento quando o prazo foi estipulado apenas em seu benefício.", "A presunção não prevalece contra cláusula ou contexto claro. Antecipação também deve respeitar a natureza da prestação e eventual interesse legítimo do credor.", "Benefício do prazo", "vantagem jurídica atribuída a uma ou a ambas as partes pela espera até o vencimento"),
    "134": row("Negócios entre vivos sem prazo podem ser exigidos imediatamente, salvo necessidade de execução em outro lugar ou de tempo para cumprir.", "Na ausência de termo, a regra é exigibilidade desde logo. A própria natureza da prestação pode, contudo, exigir deslocamento ou período razoável, impedindo cobrança instantânea incompatível com o que foi assumido.", "Entrega sem data é exigível, mas transporte a cidade distante demanda tempo material adequado.", "Exigibilidade imediata não significa execução impossível no mesmo instante. Boa-fé e características concretas da prestação orientam o tempo necessário.", "Exigibilidade", "possibilidade jurídica de cobrar o cumprimento de uma obrigação"),
    "135": row("As regras de condição suspensiva e resolutiva aplicam-se, quando compatíveis, aos termos inicial e final.", "O termo inicial aproxima-se da condição suspensiva quanto ao adiamento do exercício; o termo final aproxima-se da resolutiva quanto ao encerramento de efeitos. A aplicação é adaptada porque o termo é futuro e certo, enquanto a condição é incerta.", "Direito com data certa de término segue, no que couber, efeitos semelhantes aos da condição resolutiva.", "A remissão não apaga a diferença entre termo e condição. Só se transportam regras compatíveis com a certeza do evento temporal.", "Termo final", "marco futuro e certo que encerra os efeitos de um direito ou negócio"),
    "136": row("O encargo normalmente não impede adquirir nem exercer o direito, salvo se o disponente o tiver imposto expressamente como condição suspensiva.", "Encargo é uma obrigação atribuída ao beneficiário de uma liberalidade. Em regra, ele recebe o direito desde logo e fica obrigado a cumprir a finalidade; excepcionalmente, a redação pode fazer do cumprimento requisito para adquirir o direito.", "Pessoa recebe doação com obrigação de conservar determinado bem cultural.", "Não basta chamar uma cláusula de encargo ou condição. É necessário interpretar se ela apenas impõe dever ou realmente suspende a aquisição.", "Encargo", "dever imposto ao beneficiário de uma liberalidade"),
    "137": row("Encargo ilícito ou impossível é desconsiderado, mas invalida a liberalidade quando foi seu motivo determinante.", "A regra busca preservar o negócio retirando o encargo defeituoso. Porém, se a finalidade ilícita ou impossível foi essencial para a concessão do benefício, não há razão para manter a liberalidade.", "Doação impõe tarefa impossível sem ser essencial; o encargo cai e a doação pode subsistir.", "A solução exige apurar a importância do encargo para o disponente. Não se presume motivo determinante apenas porque a cláusula foi escrita.", "Liberalidade", "atribuição gratuita de vantagem patrimonial, como doação ou legado"),
    "138": row("Erro substancial perceptível por pessoa normalmente diligente pode tornar o negócio anulável.", "O erro precisa atingir aspecto relevante da manifestação de vontade e ser objetivamente reconhecível nas circunstâncias. Pequeno engano sem influência decisiva não basta. A consequência é anulabilidade, não nulidade automática.", "Comprador adquire obra acreditando, por erro essencial perceptível, tratar-se de original de determinado autor.", "A análise considera a relevância do erro e sua cognoscibilidade. Descuido puramente individual e irrelevante pode não autorizar anulação.", "Erro substancial", "falsa percepção essencial que influencia de modo decisivo a celebração do negócio"),
    "139": row("O erro é substancial quando recai sobre natureza ou objeto essencial do negócio, pessoa decisiva ou motivo jurídico principal que não represente recusa à lei.", "O artigo delimita erros capazes de afetar a validade. A identidade ou qualidade da pessoa só importa quando influenciou relevantemente a decisão. Erro de direito pode contar se foi motivo único ou principal, sem servir para ignorar a lei.", "Doação é feita à pessoa errada quando a identidade do beneficiário era decisiva.", "Erro sobre aspecto secundário não se torna substancial apenas porque gerou arrependimento. É necessário vínculo relevante com a vontade declarada.", "Erro de direito", "compreensão equivocada sobre norma jurídica que, em hipóteses limitadas, influencia o negócio"),
    "140": row("Motivo falso só afeta a declaração quando foi expressamente apresentado como razão determinante.", "Razões internas normalmente não integram o negócio. Para que o falso motivo vicie a vontade, ele deve ter sido exteriorizado e colocado como fundamento decisivo da declaração.", "Doação declara expressamente que ocorre por fato específico, depois comprovado inexistente.", "Motivo reservado ou apenas presumido não basta. Também é preciso distinguir motivo falso de condição ou de cláusula contratual autônoma.", "Motivo determinante", "razão expressamente indicada como decisiva para realizar o negócio"),
}

ROWS.update({
    "141": row("Erro na transmissão da vontade por mensageiro ou meio intermediário segue as mesmas hipóteses de anulabilidade da declaração direta.", "A interposição de pessoa ou tecnologia não amplia nem reduz os requisitos do erro. É preciso verificar se a divergência transmitida seria juridicamente relevante caso tivesse sido cometida pelo próprio declarante.", "Mensageiro informa preço diferente do autorizado, alterando elemento essencial perceptível do negócio.", "Nem toda falha de comunicação anula o ato. Aplicam-se os critérios de erro substancial e reconhecível, além da análise de responsabilidade pelo meio utilizado.", "Meio interposto", "pessoa ou instrumento usado para transmitir a declaração de vontade"),
    "142": row("Indicação errada de pessoa ou coisa não invalida o negócio quando o contexto permite identificar o destinatário ou objeto pretendido.", "A lei preserva a declaração se a identidade correta resulta das circunstâncias. O erro de nome ou descrição é superável quando não existe dúvida razoável sobre a vontade efetiva.", "Testamento usa apelido impreciso, mas outros dados individualizam inequivocamente o beneficiário.", "Se houver duas interpretações plausíveis ou a identidade for essencial e incerta, a regra de conservação pode não resolver o problema.", "Erro de indicação", "equívoco na designação nominal ou descritiva de pessoa ou coisa"),
    "143": row("Erro meramente aritmético autoriza corrigir o cálculo, sem desfazer o negócio.", "Quando a vontade e os elementos da operação estão corretos, mas a soma, multiplicação ou transposição numérica saiu errada, retifica-se o resultado. A solução conserva o acordo efetivamente formado.", "Contrato registra parcelas corretas, porém totaliza por engano valor superior; o total é corrigido.", "A regra não cobre erro sobre preço, quantidade ou critério de cálculo realmente negociado. Nesses casos pode existir erro substancial ou divergência contratual.", "Erro de cálculo", "falha aritmética na obtenção de um resultado a partir de elementos já definidos"),
    "144": row("O erro não invalida o negócio quando o destinatário aceita executá-lo conforme a vontade real do declarante.", "A oferta de cumprimento correto elimina o prejuízo decorrente da divergência e favorece a conservação do negócio. A adequação deve corresponder efetivamente ao que o declarante pretendia.", "Vendedor percebe que o comprador indicou por engano outro modelo e concorda em entregar o modelo realmente desejado pelo mesmo ajuste.", "A parte não pode impor versão aproximada ou mais onerosa sob pretexto de corrigir o erro. A conformidade com a vontade real precisa ser demonstrável.", "Conservação do negócio", "preferência por manter o ato quando o defeito pode ser superado sem lesar sua finalidade"),
    "145": row("Dolo que foi causa da celebração torna o negócio anulável.", "Dolo principal é a manobra intencional que induz a outra parte a contratar quando, sem ela, não teria celebrado o negócio. A consequência é anulabilidade, além de possíveis perdas e danos conforme o caso.", "Vendedor oculta deliberadamente defeito estrutural decisivo para convencer o comprador a adquirir o imóvel.", "É necessário provar conduta enganosa relevante e influência causal. Exagero irrelevante ou simples opinião não configura automaticamente dolo principal.", "Dolo principal", "engano intencional determinante para a celebração do negócio"),
    "146": row("Dolo acidental não anula o negócio, mas obriga o responsável a reparar perdas e danos.", "O dolo é acidental quando o negócio teria sido feito mesmo sem a manobra, embora em condições diferentes. Preserva-se o vínculo e indeniza-se o prejuízo causado pela distorção.", "Comprador adquiriria o bem de qualquer modo, mas pagou mais porque o vendedor falseou uma característica secundária.", "A distinção depende da influência concreta do engano sobre a decisão. Se sem ele não haveria contratação, trata-se de dolo principal.", "Dolo acidental", "engano que altera condições do negócio, mas não determina sua própria existência"),
    "147": row("Silêncio intencional sobre fato desconhecido pela outra parte pode constituir dolo em negócio bilateral quando, sem a omissão, o contrato não seria celebrado.", "A omissão torna-se juridicamente relevante quando havia informação decisiva conscientemente escondida. Exige-se vínculo causal entre o silêncio e a manifestação de vontade.", "Fornecedor sabe de impedimento essencial e o oculta para que a outra parte assine o contrato.", "O artigo não cria dever geral de revelar todo dado. Importam relevância, conhecimento, contexto, boa-fé e o caráter determinante da informação omitida.", "Omissão dolosa", "silêncio intencional sobre informação decisiva que induz a outra parte a contratar"),
    "148": row("Dolo praticado por terceiro permite anulação se o beneficiado sabia ou deveria saber; caso contrário, o negócio subsiste e o terceiro indeniza a vítima.", "A consequência varia conforme o conhecimento da parte favorecida. Ciência real ou exigível aproxima o dolo do próprio contratante; desconhecimento preserva o negócio e concentra a responsabilidade no terceiro enganador.", "Corretor mente para favorecer vendedor que conhece a manobra; o comprador pode pedir anulação.", "Não basta demonstrar o dolo do terceiro. É preciso apurar se a parte beneficiada conhecia ou deveria conhecer a fraude.", "Dolo de terceiro", "engano determinante praticado por pessoa que não é parte direta do negócio"),
    "149": row("O dolo do representante legal limita a responsabilidade do representado ao benefício recebido; no representante convencional, ambos respondem solidariamente.", "A lei diferencia representação imposta pela lei e representação escolhida pelo interessado. No primeiro caso, protege o representado além do proveito obtido; no segundo, atribui solidariedade com quem recebeu poderes voluntariamente.", "Procurador escolhido pelo representado engana a contraparte durante a contratação, gerando responsabilidade solidária por danos.", "O artigo disciplina responsabilidade civil pelo dolo do representante e não elimina outras consequências do vício sobre o negócio.", "Responsabilidade solidária", "possibilidade de cobrar integralmente a dívida de qualquer dos responsáveis"),
    "150": row("Quando ambas as partes agem com dolo, nenhuma pode usar o próprio comportamento para anular o negócio ou pedir indenização.", "A lei impede que quem também participou de manobra desleal obtenha proteção baseada no dolo recíproco. As pretensões entre os participantes ficam neutralizadas nessa matéria.", "Comprador e vendedor trocam informações deliberadamente falsas para obter vantagens um do outro.", "A regra exige dolo de ambos relacionado ao negócio. Não significa validar ilícitos contra terceiros nem afastar sanções de outras naturezas.", "Dolo recíproco", "conduta enganosa praticada por ambas as partes no mesmo negócio"),
    "151": row("Coação vicia a vontade quando provoca temor fundamentado de dano iminente e grave à pessoa, família ou bens.", "A ameaça deve ser suficientemente séria para comprometer a liberdade de decidir. Se atingir pessoa fora da família, o juiz avalia as circunstâncias para verificar relevância equivalente.", "Alguém assina contrato após ameaça concreta e imediata de grave dano ao filho.", "Pressão, insistência ou desconforto não bastam por si. Examinam-se gravidade, iminência, credibilidade e efeito sobre a vítima.", "Coação", "pressão mediante ameaça grave que compromete a liberdade da manifestação de vontade"),
    "152": row("A gravidade da coação é avaliada considerando características da vítima e todas as circunstâncias relevantes.", "A mesma ameaça pode afetar pessoas de maneira diferente. Idade, saúde, condição, temperamento e contexto ajudam a medir se houve temor capaz de viciar a vontade.", "Ameaça dirigida a pessoa fragilizada por doença é examinada levando em conta essa condição concreta.", "A avaliação individualizada não legitima estereótipos. Os fatores legais servem para compreender a capacidade real de resistência no caso.", "Circunstâncias pessoais", "características concretas consideradas para avaliar o impacto da ameaça"),
    "153": row("A ameaça de exercer normalmente um direito e o simples temor de desagradar pessoa respeitada não configuram coação.", "Cobrar legitimamente, propor ação cabível ou exercer prerrogativa dentro de seus limites não vicia a vontade. Reverência, respeito ou receio moral sem ameaça grave também não bastam.", "Credor informa que cobrará judicialmente dívida vencida; isso, sem abuso, não torna coagido o acordo.", "Exercício anormal ou abusivo de um direito pode receber avaliação diferente. Também não se confunde temor reverencial com ameaça concreta feita por autoridade familiar ou religiosa.", "Temor reverencial", "receio de desagradar alguém por respeito ou submissão moral, sem ameaça juridicamente relevante"),
    "154": row("Coação de terceiro vicia o negócio se a parte beneficiada sabia ou deveria saber, respondendo ambos solidariamente pelos danos.", "Quando o contratante aproveita ameaça alheia conhecida ou cognoscível, o vício atinge o negócio e a responsabilidade alcança beneficiado e coator.", "Terceiro ameaça vendedor, e comprador consciente da ameaça aproveita para adquirir o bem por valor reduzido.", "Devem ser comprovados a coação, o benefício e o conhecimento real ou exigível. A simples presença de terceiro não cria solidariedade.", "Coator", "pessoa que pratica a ameaça responsável por restringir a liberdade da vítima"),
    "155": row("Se a coação veio de terceiro sem conhecimento real ou exigível da parte beneficiada, o negócio permanece e o coator responde pelos danos.", "A boa-fé da parte favorecida preserva a contratação. A vítima mantém pretensão indenizatória contra quem realizou a ameaça, embora não obtenha anulação por essa regra.", "Comprador de boa-fé desconhece que terceiro ameaçou o vendedor para forçar a venda.", "A subsistência depende da ausência de conhecimento e de dever de conhecer. Outros defeitos ou ilicitudes podem conduzir a solução diversa.", "Subsistência do negócio", "manutenção da validade e dos efeitos do ato apesar de determinada irregularidade externa"),
    "156": row("Estado de perigo ocorre quando alguém assume obrigação excessivamente onerosa para evitar grave dano conhecido pela outra parte.", "A necessidade urgente de salvar a si ou familiar reduz a liberdade de negociação, e a contraparte tem ciência da situação. Para pessoa fora da família, o juiz avalia o vínculo e as circunstâncias.", "Pessoa aceita pagamento desproporcional para obter auxílio indispensável diante de risco grave conhecido pelo prestador.", "Não basta dificuldade econômica comum. Exigem-se grave dano, urgência, conhecimento da outra parte e onerosidade excessiva.", "Estado de perigo", "vício decorrente de obrigação excessiva assumida para afastar grave dano conhecido pela contraparte"),
    "157": row("Lesão ocorre quando necessidade urgente ou inexperiência leva alguém a aceitar prestação manifestamente desproporcional.", "A desproporção é medida pelos valores existentes no momento da contratação. A anulação pode ser evitada se a parte favorecida completar suficientemente a prestação ou reduzir sua vantagem.", "Pessoa inexperiente vende bem de alto valor por quantia muito inferior, em desequilíbrio manifesto.", "Lesão não exige a situação de grave dano do estado de perigo. Também não decorre de qualquer mau negócio: a desproporção deve ser manifesta e ligada à necessidade ou inexperiência.", "Lesão", "vício causado por desproporção manifesta aproveitada em situação de necessidade ou inexperiência"),
    "158": row("Transmissão gratuita ou perdão de dívida por devedor insolvente pode ser anulado por credores anteriores, inclusive quando a garantia deles se torna insuficiente.", "A fraude contra credores protege o patrimônio que responde pelas dívidas. Nos atos gratuitos, basta que o devedor já seja insolvente ou se torne insolvente com o ato, ainda que ignore a situação.", "Devedor doa seu principal imóvel e fica sem bens suficientes para pagar credores já existentes.", "A legitimidade é dos credores que já existiam quando o ato foi praticado. Credor posterior não se beneficia automaticamente desta regra.", "Credor quirografário", "credor sem garantia real ou preferência especial sobre determinado bem"),
    "159": row("Contrato oneroso do devedor insolvente é anulável quando a insolvência era notória ou deveria ser conhecida pelo outro contratante.", "Como existe contraprestação, a lei exige elemento adicional ligado à ciência do adquirente. Protege-se o terceiro de boa-fé que não tinha motivo para conhecer a insolvência.", "Empresa notoriamente insolvente vende ativo essencial a parceiro que conhece sua situação patrimonial.", "Insolvência isolada não invalida todo contrato oneroso. É necessário provar notoriedade ou motivo concreto para conhecimento pela contraparte.", "Insolvência", "situação em que o patrimônio disponível não basta para satisfazer as dívidas"),
    "160": row("Adquirente que ainda não pagou pode depositar judicialmente o preço para conservar os bens; se o preço foi baixo, deve completar até o valor real.", "O depósito protege credores e permite ao adquirente liberar-se da obrigação sem entregar valor ao devedor insolvente. Todos os interessados devem ser citados.", "Comprador deposita em juízo o preço de mercado antes de pagá-lo ao vendedor insolvente.", "Preço apenas aproximado ao corrente pode ser depositado como contratado; preço inferior exige complementação ao valor real para conservar o bem.", "Depósito judicial", "entrega de valor em juízo para produzir pagamento ou assegurar sua destinação correta"),
    "161": row("A ação por fraude pode ser dirigida ao devedor, à contraparte do negócio fraudulento e a terceiros adquirentes de má-fé.", "O artigo define o polo passivo necessário conforme a circulação do bem. Terceiro posterior só é alcançado por esta regra quando agiu de má-fé.", "Credor demanda devedor e comprador participante da fraude; revenda posterior alcança adquirente que conhecia o esquema.", "A boa-fé do subadquirente importa. A composição processual e os efeitos sobre registros e bens exigem análise do caso concreto.", "Terceiro adquirente", "pessoa que recebe o bem depois do negócio originalmente questionado"),
    "162": row("Credor sem garantia que recebe antecipadamente de devedor insolvente deve devolver o valor ao acervo comum.", "O pagamento antes do vencimento favorece indevidamente um credor em prejuízo dos demais. A reposição recompõe o patrimônio sujeito ao concurso de credores.", "Devedor insolvente antecipa dívida ainda não vencida a um credor, que deve restituir o recebido ao acervo.", "A regra trata de dívida não vencida e credor quirografário. Pagamentos vencidos e preferências legítimas exigem disciplina própria.", "Concurso de credores", "procedimento de distribuição do patrimônio insuficiente entre vários credores"),
    "163": row("Presumem-se fraudulentas as garantias dadas por devedor insolvente a um dos credores.", "Criar hipoteca, penhor ou outra garantia nessa situação altera a igualdade entre credores e concede preferência nova sobre patrimônio já insuficiente. A presunção facilita a impugnação.", "Devedor insolvente oferece imóvel em hipoteca para privilegiar dívida antes sem garantia.", "A norma não confunde garantia preexistente válida com preferência criada durante a insolvência. O momento e a natureza do ato são essenciais.", "Garantia real", "direito que vincula bem específico ao pagamento e pode conferir preferência ao credor"),
    "164": row("Negócios ordinários indispensáveis à atividade econômica ou à subsistência do devedor e da família presumem-se de boa-fé.", "A proteção evita paralisar operações normais necessárias à manutenção do estabelecimento ou da vida familiar. A presunção favorece atos compatíveis com rotina e indispensabilidade.", "Comerciante insolvente compra insumos usuais necessários para manter atividade produtiva mínima.", "Operação extraordinária, artificial ou dispensável não recebe automaticamente a proteção. A presunção pode ser confrontada por prova de fraude.", "Negócio ordinário", "operação habitual e compatível com a manutenção normal da atividade ou subsistência"),
    "165": row("Anulado o negócio fraudulento, o benefício retorna ao patrimônio comum dos credores; se havia apenas preferência indevida, anula-se somente essa preferência.", "A finalidade é recompor o acervo, não entregar diretamente o bem ao credor que ajuizou a ação. A invalidação deve atingir apenas o necessário quando o defeito se limita à garantia preferencial.", "Hipoteca fraudulenta é retirada, e o bem volta a responder sem a preferência criada.", "O resultado beneficia o concurso de credores. A extensão da anulação depende de o negócio transferir patrimônio ou apenas estabelecer preferência.", "Acervo", "conjunto de bens e direitos destinado à satisfação coletiva dos credores"),
})


